/**
 * The curated catalog of models that can actually hold a live session.
 *
 * The provider descriptors list everything an endpoint might accept; this list
 * is opinionated about what a learner should be pointed at. Realtime models are
 * shipped and withdrawn far faster than chat models, and a preview id that 404s
 * on one account works fine on another — so every entry carries a grade and an
 * explicit fallback order, and the live surface uses that order to recover
 * instead of dead-ending on "model not found".
 *
 * Pure data plus lookups: no DOM, no provider imports, so it can be unit tested
 * and reused by the settings tab and the live surface alike.
 */

export type LiveProviderId = "gemini-live" | "openai-realtime";

/**
 * How much we trust a model to carry a whole lesson.
 *
 * "recommended" — the default we hand a learner who has expressed no opinion.
 * "capable"     — fully supported, chosen deliberately or used as a fallback.
 * "legacy"      — still connects, but gives up something (usually vision).
 */
export type LiveModelGrade = "recommended" | "capable" | "legacy";

export interface LiveModelOption {
	providerId: LiveProviderId;
	value: string;
	label: string;
	grade: LiveModelGrade;
	/** How this model can see the learner, if at all. */
	video: "native" | "sampled" | "none";
	/** One line explaining the trade-off, shown next to the option. */
	note?: string;
}

/**
 * Ordered best-first per provider. The order is the fallback chain: when a
 * session fails in a way that implicates the model, the live surface offers the
 * next entry that is not the one that just failed.
 */
export const LIVE_MODELS: readonly LiveModelOption[] = [
	{
		providerId: "gemini-live",
		value: "gemini-3.1-flash-live-preview",
		label: "Gemini 3.1 Flash Live",
		grade: "recommended",
		video: "native",
		note: "Native live video and the fastest turn-taking.",
	},
	{
		providerId: "gemini-live",
		value: "gemini-2.5-flash-live-preview",
		label: "Gemini 2.5 Flash Live",
		grade: "capable",
		video: "native",
		note: "Widest availability. Runs tools without pausing the conversation.",
	},
	{
		providerId: "gemini-live",
		value: "gemini-3.0-flash-live-preview",
		label: "Gemini 3.0 Flash Live",
		grade: "capable",
		video: "native",
	},
	{
		providerId: "gemini-live",
		value: "gemini-2.0-flash-live-001",
		label: "Gemini 2.0 Flash Live",
		grade: "legacy",
		video: "native",
		note: "Older generation. Keep it for accounts without preview access.",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-realtime-2.1",
		label: "gpt-realtime-2.1",
		grade: "recommended",
		video: "sampled",
		note: "Sees sampled frames rather than live video.",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-realtime",
		label: "gpt-realtime",
		grade: "capable",
		video: "sampled",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-realtime-2.1-mini",
		label: "gpt-realtime-2.1-mini",
		grade: "capable",
		video: "sampled",
		note: "Cheaper and quicker; less patient with a long explanation.",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-realtime-mini",
		label: "gpt-realtime-mini",
		grade: "capable",
		video: "sampled",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-4o-realtime-preview-2024-12-17",
		label: "gpt-4o-realtime-preview",
		grade: "legacy",
		video: "none",
		note: "Voice only — this generation cannot look at your camera or screen.",
	},
	{
		providerId: "openai-realtime",
		value: "gpt-4o-mini-realtime-preview-2024-12-17",
		label: "gpt-4o-mini-realtime-preview",
		grade: "legacy",
		video: "none",
		note: "Voice only — this generation cannot look at your camera or screen.",
	},
] as const;

export function isLiveProviderId(id: string): id is LiveProviderId {
	return id === "gemini-live" || id === "openai-realtime";
}

export function liveModelsFor(providerId: string): LiveModelOption[] {
	return LIVE_MODELS.filter((model) => model.providerId === providerId);
}

export function findLiveModel(providerId: string, value: string): LiveModelOption | undefined {
	return LIVE_MODELS.find((model) => model.providerId === providerId && model.value === value);
}

export function recommendedLiveModel(providerId: string): LiveModelOption | undefined {
	const models = liveModelsFor(providerId);
	return models.find((model) => model.grade === "recommended") ?? models[0];
}

/**
 * The model to offer after `failing` let the learner down.
 *
 * Walks the provider's list in order, skipping the failed model and anything
 * already tried in this session, so repeatedly hitting "try another model"
 * works down the chain instead of bouncing between the same two entries.
 */
export function nextBestLiveModel(
	providerId: string,
	failing: string,
	alreadyTried: readonly string[] = [],
): LiveModelOption | undefined {
	const exhausted = new Set([failing, ...alreadyTried]);
	return liveModelsFor(providerId).find((model) => !exhausted.has(model.value));
}

/** Label for a model id that is not in the catalog (a hand-typed override). */
export function describeLiveModel(providerId: string, value: string): LiveModelOption {
	return findLiveModel(providerId, value) ?? {
		providerId: (isLiveProviderId(providerId) ? providerId : "gemini-live"),
		value,
		label: value,
		grade: "capable",
		video: providerId === "gemini-live" ? "native" : "sampled",
		note: "Not in Keating's tested list — it may refuse the session.",
	};
}
import type { AgentTool } from "@earendil-works/pi-agent-core";
import { createLocalSetting } from "./local-setting";
import type { ConversationEvent } from "./protocol";
import type { VideoCaptureHandle, VideoSource } from "./video-capture";
import {
	resolveRealtimeTier,
	type ProviderModelDescriptor,
	type RealtimeTierDescriptor,
} from "./providers";

export const KEATING_VOICE_TOOL_NAME = "keating_voice";
export const GEMINI_LIVE_SPEECH_MODEL = "gemini-3.1-flash-live-preview";
export const DEFAULT_SPEECH_VOICE = "Kore";
const SPEECH_SETTINGS_KEY = "keating:web:speech";
export const RECEIVE_SAMPLE_RATE = 24_000;

const VOICE_TAGS = new Set([
	"explain",
	"question",
	"verify",
	"redirect",
	"encourage",
	"pause",
	"recap",
]);

export type SpeechProviderId =
	| "gemini-live"
	| "openai-tts"
	| "openai-realtime"
	| "supertonic-3"
	| string; // allows "custom:<id>"

export interface CustomSpeechModel {
	id: string;            // stable client id; storage key is `custom:${id}`
	label: string;         // shown in dropdown
	baseUrl: string;       // for OpenAI-compatible TTS endpoints
	model: string;         // model id passed in request body
	voice: string;         // default voice
	providerKey: string;   // which providerKeys entry to use ("openai", custom name)
	apiPath?: string;      // default "/v1/audio/speech"
}

export interface WebSpeechSettings {
	enabled: boolean;
	/** Active provider. Defaults to "gemini-live" for back-compat. */
	providerId: SpeechProviderId;
	/** Active model for the chosen provider. */
	model: string;
	/** Active voice for the chosen provider. */
	voiceName: string;
	/** User-defined OpenAI-compatible TTS endpoints. */
	customModels: CustomSpeechModel[];
	/** When true, Realtime providers may capture mic input. */
	microphoneEnabled: boolean;
	/** When true, live sessions may capture camera or screen frames. */
	videoEnabled: boolean;
	/** Where live-session frames come from. */
	videoSource: VideoSource;
	/** Milliseconds between sampled frames; floored to 1 fps by the capture layer. */
	frameIntervalMs: number;
	/** Reasoning budget for Realtime reasoning models. */
	reasoningEffort: "minimal" | "low" | "medium" | "high" | "xhigh";
}

export interface VoiceUtterance {
	text: string;
	voice: string;
	tags: string[];
	pace: string;
	affect: string;
}

export const DEFAULT_WEB_SPEECH_SETTINGS: WebSpeechSettings = {
	enabled: false,
	providerId: "gemini-live",
	model: GEMINI_LIVE_SPEECH_MODEL,
	voiceName: DEFAULT_SPEECH_VOICE,
	customModels: [],
	microphoneEnabled: false,
	videoEnabled: false,
	videoSource: "camera",
	frameIntervalMs: 1000,
	reasoningEffort: "medium",
};

const speechSetting = createLocalSetting<WebSpeechSettings>({
	key: SPEECH_SETTINGS_KEY,
	event: "keating:web:speech-changed",
	normalize: (raw) => {
		if (typeof raw !== "string" || raw.length === 0) return DEFAULT_WEB_SPEECH_SETTINGS;
		try {
			const parsed = JSON.parse(raw) as Partial<WebSpeechSettings>;
			const customModels = Array.isArray(parsed.customModels)
				? parsed.customModels.filter(
						(m): m is CustomSpeechModel =>
							!!m && typeof m.id === "string" && typeof m.baseUrl === "string" && typeof m.model === "string",
					)
				: [];
			return {
				enabled: parsed.enabled === true,
				providerId: cleanString(parsed.providerId) || DEFAULT_WEB_SPEECH_SETTINGS.providerId,
				model: cleanString(parsed.model) || DEFAULT_WEB_SPEECH_SETTINGS.model,
				voiceName: cleanString(parsed.voiceName) || DEFAULT_WEB_SPEECH_SETTINGS.voiceName,
				customModels,
				microphoneEnabled: parsed.microphoneEnabled === true,
				videoEnabled: parsed.videoEnabled === true,
				videoSource: parsed.videoSource === "screen" ? "screen" : "camera",
				frameIntervalMs: Number.isFinite(parsed.frameIntervalMs) && (parsed.frameIntervalMs ?? 0) > 0
					? Math.floor(parsed.frameIntervalMs as number)
					: DEFAULT_WEB_SPEECH_SETTINGS.frameIntervalMs,
				reasoningEffort: ["minimal", "low", "medium", "high", "xhigh"].includes(parsed.reasoningEffort ?? "")
					? parsed.reasoningEffort as WebSpeechSettings["reasoningEffort"]
					: DEFAULT_WEB_SPEECH_SETTINGS.reasoningEffort,
			};
		} catch {
			return DEFAULT_WEB_SPEECH_SETTINGS;
		}
	},
});

function cleanString(value: unknown): string {
	return typeof value === "string" ? value.trim() : "";
}

function cleanTags(value: unknown): string[] {
	const rawTags = Array.isArray(value) ? value : typeof value === "string" ? value.split(",") : [];
	const tags = rawTags
		.map((tag) => cleanString(tag).toLowerCase())
		.filter((tag) => VOICE_TAGS.has(tag));
	return Array.from(new Set(tags));
}

export function normalizeVoiceUtterance(input: Record<string, unknown>, settings: WebSpeechSettings): VoiceUtterance {
	const text = cleanString(input.text);
	if (!text) throw new Error("keating_voice requires non-empty text.");

	return {
		text,
		voice: cleanString(input.voice) || settings.voiceName,
		tags: cleanTags(input.tags ?? input.tag),
		pace: cleanString(input.pace) || "conversational",
		affect: cleanString(input.affect) || "warm",
	};
}

export function voiceTagLine(utterance: VoiceUtterance): string {
	const tags = utterance.tags.length ? utterance.tags.join(",") : "none";
	return `[voice voice=${utterance.voice} tags=${tags} pace=${utterance.pace} affect=${utterance.affect}] ${utterance.text}`;
}

export function loadWebSpeechSettings(): WebSpeechSettings {
	return speechSetting.load();
}

export function saveWebSpeechSettings(settings: WebSpeechSettings): void {
	speechSetting.save(settings);
}

export function subscribeWebSpeechSettings(callback: (settings: WebSpeechSettings) => void): () => void {
	return speechSetting.subscribe(callback);
}

export type SpeechCredentialProvider = "openai" | "google";

export interface SpeechCredential {
	provider: SpeechCredentialProvider;
	apiKey: string;
}

/**
 * Pick the credential used for speech input (STT / realtime). Prefers a genuine
 * OpenAI key, then Google/Gemini. The OpenAI check uses the "openai" provider
 * only — that is the real api.openai.com. A custom-base OpenAI-compatible
 * provider is stored under its own name and is intentionally NOT treated as an
 * OpenAI speech credential, since the transcription/realtime endpoints are
 * OpenAI-specific.
 */
export async function resolveSpeechCredential(
	getApiKey: (provider: string) => Promise<string | undefined>,
): Promise<SpeechCredential | null> {
	const openai = await getApiKey("openai");
	if (openai) return { provider: "openai", apiKey: openai };
	const google = await getApiKey("google");
	if (google) return { provider: "google", apiKey: google };
	return null;
}

const DUPLEX_PROVIDER_IDS = new Set<SpeechProviderId>(["gemini-live", "openai-realtime"]);

export function isDuplexSpeechProvider(id: SpeechProviderId): boolean {
	return DUPLEX_PROVIDER_IDS.has(id);
}

/**
 * Decide whether the prompt mic button should open a live bidirectional session
 * or do one-shot speech-to-text. Duplex only when speech is enabled and the
 * active provider is a duplex provider (OpenAI Realtime / Gemini Live).
 */
export function speechInputMode(settings: WebSpeechSettings): "duplex" | "stt" {
	return settings.enabled && settings.microphoneEnabled && isDuplexSpeechProvider(settings.providerId) ? "duplex" : "stt";
}

/** Which LLM provider backs a speech provider, for capability lookup. */
export function speechProviderModel(settings: WebSpeechSettings): ProviderModelDescriptor | null {
	if (settings.providerId === "openai-realtime") return { provider: "openai", id: settings.model, api: "openai-realtime" };
	if (settings.providerId === "gemini-live") return { provider: "google", id: settings.model, api: "google-live" };
	return null;
}

/**
 * The realtime tier the current speech settings can actually be driven at.
 * Non-duplex providers (plain TTS, custom endpoints) are tier 0 by definition.
 */
export function resolveSpeechRealtimeTier(settings: WebSpeechSettings): RealtimeTierDescriptor {
	const model = speechProviderModel(settings);
	if (!model) {
		return {
			tier: 0,
			label: "Half duplex (push to talk)",
			video: false,
			videoRoute: "none",
			capReason: "This provider only synthesizes speech; it cannot hold a live session.",
		};
	}
	return resolveRealtimeTier(model);
}

let audioContext: AudioContext | null = null;
let scheduledUntil = 0;
/** Sources queued but not yet finished, so barge-in can cut them off. */
const scheduledSources = new Set<AudioBufferSourceNode>();

export function getAudioContext(): AudioContext | null {
	if (typeof window === "undefined") return null;
	const AudioContextCtor = window.AudioContext || window.webkitAudioContext;
	if (!AudioContextCtor) return null;
	audioContext ??= new AudioContextCtor();
	return audioContext;
}

export async function primeSpeechAudio(): Promise<void> {
	const context = getAudioContext();
	if (context && context.state === "suspended") await context.resume();
}

function decodeBase64Pcm(base64: string): Int16Array {
	const binary = window.atob(base64);
	const bytes = new Uint8Array(binary.length);
	for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
	return new Int16Array(bytes.buffer);
}

export function schedulePcmAudio(base64: string, sampleRate = RECEIVE_SAMPLE_RATE): boolean {
	const context = getAudioContext();
	if (!context) return false;

	const pcm = decodeBase64Pcm(base64);
	if (pcm.length === 0) return false;

	const buffer = context.createBuffer(1, pcm.length, sampleRate);
	const channel = buffer.getChannelData(0);
	for (let i = 0; i < pcm.length; i += 1) channel[i] = pcm[i] / 32768;

	const source = context.createBufferSource();
	source.buffer = buffer;
	source.connect(context.destination);
	const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
	source.start(startAt);
	scheduledUntil = startAt + buffer.duration;
	trackScheduledSource(source);
	return true;
}

function trackScheduledSource(source: AudioBufferSourceNode): void {
	scheduledSources.add(source);
	source.addEventListener("ended", () => scheduledSources.delete(source), { once: true });
}

/**
 * Cut off audio that has been queued but not yet played.
 *
 * Providers that stream PCM (rather than delivering a WebRTC track) can have
 * seconds of assistant speech buffered ahead of the speaker. Without this, a
 * learner interrupting would keep hearing the sentence they just cut off.
 */
export function stopScheduledAudio(): void {
	for (const source of scheduledSources) {
		try {
			source.stop();
		} catch {
			// Already stopped or never started; either way it is not audible.
		}
	}
	scheduledSources.clear();
	const context = getAudioContext();
	scheduledUntil = context ? context.currentTime : 0;
}

export async function scheduleAudioBlob(blob: Blob): Promise<boolean> {
	const context = getAudioContext();
	if (!context) return false;
	const arrayBuffer = await blob.arrayBuffer();
	const audioBuffer = await context.decodeAudioData(arrayBuffer.slice(0));
	const source = context.createBufferSource();
	source.buffer = audioBuffer;
	source.connect(context.destination);
	const startAt = Math.max(context.currentTime + 0.03, scheduledUntil);
	source.start(startAt);
	scheduledUntil = startAt + audioBuffer.duration;
	trackScheduledSource(source);
	return true;
}

export function speechErrorMessage(error: unknown, fallback: string): string {
	if (error instanceof Error && error.message.trim()) return error.message.trim();
	if (typeof error === "string" && error.trim()) return error.trim();
	return fallback;
}

export interface SpeechSynthesisResult {
	audioChunks: number;
	playedChunks: number;
	transcript: string;
	warning?: string;
}

export interface SpeechSynthesisRequest {
	utterance: VoiceUtterance;
	settings: WebSpeechSettings;
	customModel?: CustomSpeechModel;
	getApiKey: (provider: string) => Promise<string | undefined>;
	signal?: AbortSignal;
}

export interface SpeechProviderDescriptor {
	id: SpeechProviderId;
	label: string;
	kind: "tts" | "duplex";
	status: "stable" | "preview" | "experimental";
	description: string;
	models: { value: string; label: string }[];
	voices: string[];
	needsApiKey?: string;
}

export type LiveSpeechState = "connecting" | "listening" | "speaking" | "closed";

export interface LiveSpeechTool {
	name: string;
	description: string;
	parameters: Record<string, unknown>;
}

export interface LiveSpeechToolCall {
	callId: string;
	name: string;
	arguments: Record<string, unknown>;
}

import {
	getAudioContext,
	type LiveHistoryTurn,
	type LiveSpeechRequest,
	type LiveSpeechSession,
	type LiveSpeechState,
	type LiveSpeechTool,
	type SpeechProvider,
	type SpeechSynthesisRequest,
	type SpeechSynthesisResult,
} from "../speech";
import { withApiRetry } from "../api-retry";
import { negotiateProviderCapabilities } from "../providers";
import {
	createRealtimeTelemetry,
	type RealtimeTelemetryObserver,
} from "../observability";
import type { CapturedFrame } from "../video-capture";
import {
	createRealtimeCanonicalBridge,
	jsonRecord,
	parseToolArguments,
	protocolError as sharedProtocolError,
	runLiveToolCall,
} from "./live-session-shared";

export {
	createRealtimeCanonicalBridge,
	type RealtimeCanonicalBridge,
} from "./live-session-shared";

/** Tool the model can call to look at what the learner is showing right now. */
export const LOOK_AT_SCREEN_TOOL_NAME = "look_at_screen";

const LOOK_AT_SCREEN_TOOL: LiveSpeechTool = {
	name: LOOK_AT_SCREEN_TOOL_NAME,
	description:
		"Look at what the learner is currently showing on their camera or shared screen. "
		+ "Call this when the learner refers to something visual ('this', 'here', 'what I'm holding') "
		+ "or when you need to check their work before answering.",
	parameters: { type: "object", properties: {}, additionalProperties: false },
};

function protocolError(error: unknown, code: string) {
	return sharedProtocolError(error, code, "openai");
}

export function negotiateOpenAIRealtimeSession(model: string) {
	return negotiateProviderCapabilities(
		{ provider: "openai", id: model, api: "openai-realtime" },
		{ realtimeAudio: true, toolCalls: true, preferredTransports: ["webrtc"], allowAdapters: false },
	);
}

/** Only the reasoning-capable realtime models accept a reasoning budget. */
function supportsReasoningEffort(model: string): boolean {
	return /^gpt-realtime-2/i.test(model);
}

/**
 * Session configuration in the current nested shape.
 *
 * Turn detection, transcription, and voice all live under `audio.input` /
 * `audio.output`. The older flat layout (`turn_detection` and
 * `input_audio_transcription` at the session root) is silently ignored by the
 * GA endpoint, which means those settings never took effect.
 */
export function buildRealtimeSessionConfig(
	settings: LiveSpeechRequest["settings"],
	instructions?: string,
	tools: LiveSpeechTool[] = [],
): Record<string, unknown> {
	return {
		type: "realtime",
		output_modalities: ["audio"],
		audio: {
			input: {
				format: { type: "audio/pcm", rate: 24_000 },
				// Semantic VAD waits on meaning rather than a fixed silence
				// window, so a learner thinking mid-sentence is not cut off.
				turn_detection: { type: "semantic_vad", create_response: true, interrupt_response: true },
				transcription: { model: "gpt-4o-transcribe" },
			},
			output: {
				format: { type: "audio/pcm" },
				voice: cleanRealtimeVoice(settings.voiceName),
			},
		},
		...(supportsReasoningEffort(settings.model) ? { reasoning: { effort: settings.reasoningEffort } } : {}),
		...(instructions ? { instructions } : {}),
		...(tools.length > 0 ? {
			tools: tools.map((tool) => ({ type: "function", ...tool })),
			tool_choice: "auto",
		} : {}),
	};
}

export function buildRealtimeSessionUpdate(
	settings: LiveSpeechRequest["settings"],
	instructions?: string,
	tools: LiveSpeechTool[] = [],
): Record<string, unknown> {
	return {
		type: "session.update",
		session: buildRealtimeSessionConfig(settings, instructions, tools),
	};
}

export function realtimeFunctionOutput(callId: string, output: unknown): Record<string, unknown> {
	return {
		type: "conversation.item.create",
		item: {
			type: "function_call_output",
			call_id: callId,
			output: typeof output === "string" ? output : JSON.stringify(output),
		},
	};
}

/**
 * A sampled frame, as a conversation item.
 *
 * Realtime has no video lane, so vision arrives as still images attached to the
 * conversation. Deliberately not followed by `response.create`: a frame is
 * context for the next turn, not a turn of its own, and forcing a response on
 * every frame would make the model narrate the camera feed.
 */
export function realtimeImageItem(dataUrl: string): Record<string, unknown> {
	return {
		type: "conversation.item.create",
		item: {
			type: "message",
			role: "user",
			content: [{ type: "input_image", image_url: dataUrl }],
		},
	};
}

/** Seed a prior chat turn so a voice session continues the same conversation. */
export function realtimeHistoryItem(turn: LiveHistoryTurn): Record<string, unknown> {
	return {
		type: "conversation.item.create",
		item: {
			type: "message",
			role: turn.role,
			content: [{
				type: turn.role === "assistant" ? "output_text" : "input_text",
				text: turn.text,
			}],
		},
	};
}

const REALTIME_MODELS = [
	{ value: "gpt-realtime-2.1", label: "gpt-realtime-2.1 (latest)" },
	{ value: "gpt-realtime-2.1-mini", label: "gpt-realtime-2.1-mini" },
	{ value: "gpt-realtime-2", label: "gpt-realtime-2" },
	{ value: "gpt-realtime", label: "gpt-realtime" },
	{ value: "gpt-realtime-mini", label: "gpt-realtime-mini" },
	{ value: "gpt-4o-realtime-preview-2024-12-17", label: "gpt-4o-realtime-preview" },
	{ value: "gpt-4o-mini-realtime-preview-2024-12-17", label: "gpt-4o-mini-realtime-preview" },
];

const REALTIME_VOICES = [
	"alloy",
	"ash",
	"ballad",
	"cedar",
	"coral",
	"echo",
	"marin",
	"sage",
	"shimmer",
	"verse",
];

function cleanRealtimeVoice(value: string | undefined): string {
	const requested = (value ?? "").trim().toLowerCase();
	return REALTIME_VOICES.includes(requested) ? requested : "marin";
}

async function mintEphemeralKey(apiKey: string, model: string, voice: string, signal?: AbortSignal): Promise<string> {
	const response = await withApiRetry(async () => {
		const result = await fetch("https://api.openai.com/v1/realtime/client_secrets", {
			method: "POST",
			headers: {
				"Content-Type": "application/json",
				Authorization: `Bearer ${apiKey}`,
			},
			body: JSON.stringify({
